    -- addon:toolbelt.chat_forge:text
    ["A forge and an anvil stand beside you for {minutes} minutes."] = "Una forja y un yunque se alzan a tu lado durante {minutes} minutos.",
    -- addon:data.petdesc.69535:text
    ["A gift from the Wildhammer dwarves to the heroes of the Alliance, these hatchlings are descendants of the same gryphons ridden by Falstad and his entourage into Grim Batol."] = "Regalo de los enanos Martillo Salvaje a los héroes de la Alianza, estas crías descienden de los mismos grifos que montaron Falstad y su séquito hasta Grim Batol.",
