    -- addon:data.petdesc.40634:text
    ["Domesticated elekks are trained as mounts by the draenei people. In the wild they are hunted for their ivory tusks."] = "Los elekks domesticados son adiestrados como monturas por los draenei. En libertad, se los caza por sus colmillos de marfil.",
    -- addon:data.petdesc.13548:text
