    -- addon:data.affix_text.during_bladestorm_you_take_value_10_valu:text
    ["During Bladestorm you take @value@10%@value@ @range@[6%-30%]@range@ less damage, and each enemy you hit heals you for 1 % of your health (Does not stack)"] = "Durante Filotormenta recibes un @value@10%@value@ @range@[6%-30%]@range@ menos de daño, y cada enemigo al que golpeas te sana un 1 % de tu salud (No se acumula)",
    -- addon:data.affix_text.during_bladestorm_you_take_value_14_valu:text
    ["During Bladestorm you take @value@14%@value@ @range@[6%-30%]@range@ less damage, and each enemy you hit heals you for 1 % of your health (Does not stack)"] = "Durante Filotormenta recibes un @value@14%@value@ @range@[6%-30%]@range@ menos de daño, y cada enemigo al que golpeas te sana un 1 % de tu salud (No se acumula)",
    -- addon:data.affix_text.during_bladestorm_you_take_value_20_valu:text
