    ["Enchantments, gems and its affix are kept."] = "Se conservan los encantamientos, las gemas y su afijo.",
    -- addon:data.affix_text.enemies_frozen_by_your_frost_nova_are_ta:text
    ["Enemies frozen by your Frost Nova are tainted. When the freeze breaks, each one bursts for @value@200%@value@ @range@[40%-200%]@range@ of your Spell Power as Nature damage and freezes enemies around it for 2 sec. A burst cannot trigger another burst (Does not stack)"] = "Los enemigos congelados por tu Nova de Escarcha quedan contaminados. Cuando se rompe la congelación, cada uno estalla con daño de Naturaleza equivalente al @value@200%@value@ @range@[40%-200%]@range@ de tu poder con hechizos y congela a los enemigos de alrededor durante 2 s. Un estallido no puede provocar otro (No se acumula)",
    -- addon:data.affix_text.enemies_killed_by_scourge_strike_explode:text
    ["Enemies killed by Scourge Strike explode after 2 sec: @value@150%@value@ @range@[30%-150%]@range@ of your Attack Power as Shadow damage to enemies within 8 yd (Does not stack)"] = "Los enemigos que mueren por Golpe de la Plaga explotan tras 2 s: daño de Sombras equivalente al @value@150%@value@ @range@[30%-150%]@range@ de tu poder de ataque a los enemigos en un radio de 8 m (No se acumula)",
    -- addon:data.affix_text.enemies_killed_by_scourge_strike_give_yo:text
    ["Enemies killed by Scourge Strike give you @value@30@value@ @range@[10-30]@range@ runic power and explode in plague after 2 sec for 20 % of your Attack Power as Shadow damage to enemies within 8 yd (Does not stack)"] = "Los enemigos que mueren por Golpe de la Plaga te otorgan @value@30@value@ @range@[10-30]@range@ p. de poder rúnico y tras 2 s explotan en una nube de peste que inflige daño de Sombras equivalente al 20 % de tu poder de ataque a los enemigos en un radio de 8 m (No se acumula)",
    -- addon:data.affix_text.enemies_standing_in_your_consecration_de:text
    ["Enemies standing in your Consecration deal @value@15%@value@ @range@[3%-15%]@range@ less damage to your allies and are slowed by 20 % (Does not stack)"] = "Los enemigos situados en tu Consagración infligen un @value@15%@value@ @range@[3%-15%]@range@ menos de daño a tus aliados y sufren una ralentización del 20 % (No se acumula)",
