    -- addon:data.petdesc.49964:text
    ["Ethereal soul-traders will travel with those who can free the essences they need from unruly hosts."] = "Los mercaderes de almas etéreos viajarán con quienes sean capaces de liberar de huéspedes rebeldes las esencias que necesitan.",
    -- addon:data.affix_family.evasive:text
    ["Evasive"] = "Evasiva",
    -- addon:data.mountdesc.60025:text
    ["Even the Draconic Native Association tests proved inconclusive in determining if the albino drake is related to a known dragonflight. -Breanni"] = "Ni siquiera las pruebas de la Asociación de Nativos Dracónicos han logrado determinar si el draco albino está emparentado con algún vuelo de dragones conocido. -Breanni",
    -- addon:data.mountdesc.55164:text
    ["Even the dead need a lift every now and then."] = "Hasta los muertos necesitan que los lleven de vez en cuando.",
