    -- addon:data.affix_text.every_12_sec_shields_you_for_value_1_2_v:text
    ["Every 12 sec, shields you for @value@1,2%@value@ @range@[1,2%-6%]@range@ of your maximum health for 12 sec (Does not stack)"] = "Cada 12 s, te protege con un escudo equivalente al @value@1,2%@value@ @range@[1,2%-6%]@range@ de tu salud máxima durante 12 s (No se acumula)",
    -- addon:data.affix_text.every_12_sec_shields_you_for_value_2_val:text
    ["Every 12 sec, shields you for @value@2%@value@ @range@[1,2%-6%]@range@ of your maximum health for 12 sec (Does not stack)"] = "Cada 12 s, te protege con un escudo equivalente al @value@2%@value@ @range@[1,2%-6%]@range@ de tu salud máxima durante 12 s (No se acumula)",
    -- addon:data.affix_text.every_12_sec_shields_you_for_value_3_val:text
    ["Every 12 sec, shields you for @value@3%@value@ @range@[1,2%-6%]@range@ of your maximum health for 12 sec (Does not stack)"] = "Cada 12 s, te protege con un escudo equivalente al @value@3%@value@ @range@[1,2%-6%]@range@ de tu salud máxima durante 12 s (No se acumula)",
    -- addon:data.affix_text.every_12_sec_shields_you_for_value_4_val:text
    ["Every 12 sec, shields you for @value@4%@value@ @range@[1,2%-6%]@range@ of your maximum health for 12 sec (Does not stack)"] = "Cada 12 s, te protege con un escudo equivalente al @value@4%@value@ @range@[1,2%-6%]@range@ de tu salud máxima durante 12 s (No se acumula)",
    -- addon:data.affix_text.every_12_sec_shields_you_for_value_6_val:text
    ["Every 12 sec, shields you for @value@6%@value@ @range@[1,2%-6%]@range@ of your maximum health for 12 sec (Does not stack)"] = "Cada 12 s, te protege con un escudo equivalente al @value@6%@value@ @range@[1,2%-6%]@range@ de tu salud máxima durante 12 s (No se acumula)",
    -- addon:skillTree.every_soul_ash_you_earn:text
    ["Every Soul Ash you earn while playing a {classId} raises this bar. Each class level lets you own one more node of this constellation, bought for good with Soul Ashes."] = "Cada Ceniza de alma que ganes jugando como {classId} sube esta barra. Cada nivel de clase te permite poseer un nodo más de esta constelación, comprado para siempre con Cenizas de alma.",
    -- addon:prestige.every_soul_ash_you_have:text
    ["Every Soul Ash you have committed is destroyed. Your banked Soul Shards are consumed and mint Soul Essence, the only currency a prestige never takes back."] = "Toda Ceniza de alma que hayas invertido se destruye. Tus Fragmentos de alma depositados se consumen y generan Esencia de alma, la única moneda que un prestigio nunca se lleva.",
    -- addon:playerRun.every_spirit_healer_offers_death:text
    ["Every Spirit Healer offers |cffffd700Death contracts|r: kill 50 creatures in a zone, or every boss of a dungeon or a raid. Each one you fulfil raises this bar. Then make an |cffffd700offering|r at any Spirit Healer: your run's Soul Ashes and Shards go to your account multiplied by |cffffd700(1 + bonus)|r. The bonus then starts over and your run goes on. Five offerings a week."] = "Todos los Ángeles de la Resurrección ofrecen |cffffd700contratos de muerte|r: matar a 50 criaturas en una zona, o a todos los jefes de una mazmorra o una banda. Cada uno que cumplas hace subir esta barra. Después haz una |cffffd700ofrenda|r a cualquier Ángel de la Resurrección: las Cenizas de alma y los Fragmentos de alma de tu expedición pasan a tu cuenta multiplicados por |cffffd700(1 + bonificación)|r. Luego la bonificación vuelve a empezar y tu expedición continúa. Cinco ofrendas por semana.",
    -- addon:callboard.every_claimed_contract_counts_toward:text
    ["Every claimed contract counts toward a cache. When the bar fills you receive a Hero's Call Cache: open it to take one piece of gear for your class and spec, above the item level you wear at that moment."] = "Cada contrato reclamado cuenta para un alijo. Cuando se llena la barra, recibes un Alijo de Llamada del Héroe: ábrelo para obtener una pieza de equipo para tu clase y especialización, por encima del nivel de objeto que lleves en ese momento.",
    -- addon:contracts.every_contract_fulfilled:text
    ["Every contract fulfilled"] = "Todos los contratos cumplidos",
    -- addon:core.every_dungeon_you_complete_through:text
    ["Every dungeon you complete through the Dungeon Finder earns Orbs of Lost Memories."] = "Cada mazmorra que completes a través del Buscador de mazmorras te otorga Orbes de los recuerdos perdidos.",
    -- addon:journal.every_echo_you_are_holding:text
    ["Every echo you are holding in the |cffffd700current run|r. Echoes are temporary powers picked as you level up; they fade when the run ends.\n\nRight-click a locked echo to free its slot."] = "Todos los ecos que tienes en la |cffffd700expedición actual|r. Los Ecos son poderes temporales que eliges al subir de nivel; se desvanecen cuando termina la expedición.\n\nHaz clic derecho en un eco bloqueado para liberar su ranura.",
    -- addon:data.affix_text.every_fifth_swipe_ends_with_onyxia_s_tai:text
    ["Every fifth Swipe ends with Onyxia's Tail Sweep: @value@200%@value@ @range@[40%-200%]@range@ of your Attack Power to every enemy within 8 yd of you, and they are knocked back (Does not stack)"] = "Cada quinto Flagelo termina con el Barrido de cola de Onyxia: daño equivalente al @value@200%@value@ @range@[40%-200%]@range@ de tu poder de ataque a todos los enemigos en un radio de 8 m, que además salen despedidos hacia atrás (No se acumula)",
    -- addon:perks.every_level_up_during_a_run_offers_a_dra:text
    ["Every level up during a run offers a draw of echoes: temporary powers that last until the run ends. Click a |cffffd700card|r to claim it; the card's color shows its quality.\n\n|cffffd700Freeze|r holds a card for your next draw, |cffffd700Banish|r removes it from this run's pool."] = "Cada subida de nivel durante una expedición ofrece una tirada de ecos: poderes temporales que duran hasta que termina la expedición. Haz clic en una |cffffd700carta|r para quedártela; el color de la carta indica su calidad.\n\n|cffffd700Congelar|r reserva una carta para tu siguiente tirada y |cffffd700Desterrar|r la retira del conjunto de esta expedición.",
    -- addon:perks.tut_choices_text:text
    ["Every level up during a run offers a draw of echoes: temporary powers that last until the run ends. Click |cffffd700Select|r to claim one; the card's color shows its quality.\n\n|cffffd700Freeze|r holds a card for your next draw, |cffffd700Banish|r removes it from this run's pool."] = "Cada subida de nivel durante una expedición ofrece una tirada de ecos: poderes temporales que duran hasta que termina la expedición. Haz clic en |cffffd700Seleccionar|r para quedarte con uno; el color de la carta indica su calidad.\n\n|cffffd700Congelar|r reserva una carta para tu próxima tirada y |cffffd700Desterrar|r la retira de las opciones de esta expedición.",
    -- addon:journal.every_level_up_during_a:text
    ["Every level up during a |cffffd700run|r offers you a new echo. These powers are temporary: they fade when the run ends.\n\nThe slots above are |cffffd700Permanent Echo Slots|r. Lock one of your echoes into a slot and it stays with you |cffffd700across runs|r, even through death. You unlock more slots by reaching |cffffd700Soul Ash milestones|r in your Skill Tree.\n\nClick an empty slot, then pick one of your echoes below to make it permanent.\nRight-click a locked echo to free the slot.\n\nPlaying with a |cffffd700build|r (see the Loadouts tab)? Its missing echoes appear |cff808080greyed out|r below until you collect them."] = "Cada subida de nivel durante una |cffffd700expedición|r te ofrece un nuevo eco. Estos poderes son temporales: se desvanecen cuando termina la expedición.\n\nLas ranuras de arriba son |cffffd700Ranuras de Eco permanentes|r. Bloquea uno de tus ecos en una ranura y se quedará contigo |cffffd700entre expediciones|r, incluso tras la muerte. Desbloqueas más ranuras al alcanzar |cffffd700hitos de Ceniza de alma|r en tu Árbol de Cenizas.\n\nHaz clic en una ranura vacía y luego elige uno de tus ecos de abajo para hacerlo permanente.\nHaz clic derecho en un eco bloqueado para liberar la ranura.\n\n¿Juegas con una |cffffd700build|r (consulta la pestaña Configuraciones)? Los ecos que le faltan aparecen |cff808080en gris|r abajo hasta que los consigas.",
    -- addon:skillTree.every_point_of_experience_you:text
    ["Every point of experience you gain during a run turns into Soul Ashes. When the run ends, they are banked on your account for good."] = "Cada punto de experiencia que ganas durante una expedición se convierte en Cenizas de alma. Cuando termina la expedición, se guardan en tu cuenta para siempre.",
    -- addon:skillTree.every_rank_is_for_good:text
    ["Every rank is for good"] = "Cada rango es para siempre",
    -- addon:dungeonFinder.every_run:text
    ["Every run"] = "Cada expedición",
    -- addon:data.affix_text.every_third_crusader_strike_becomes_a_wh:text
    ["Every third Crusader Strike becomes a Whirling Slash: @value@150%@value@ @range@[30%-150%]@range@ of your Attack Power to every enemy within 8 yd (Does not stack)"] = "Cada tercer Golpe de cruzado se convierte en un Tajo giratorio: daño equivalente al @value@150%@value@ @range@[30%-150%]@range@ de tu poder de ataque a todos los enemigos en un radio de 8 m (No se acumula)",
    -- addon:data.affix_text.every_third_lava_lash_strikes_volkhan_s:text
    ["Every third Lava Lash strikes Volkhan's anvil: a Molten Golem rises and fights for you for 10 sec, dealing @value@50%@value@ @range@[10%-50%]@range@ of your Attack Power every second (Does not stack)"] = "Cada tercer Latigazo de lava golpea el yunque de Volkhan: un Gólem fundido se alza y lucha por ti durante 10 s, e inflige daño equivalente al @value@50%@value@ @range@[10%-50%]@range@ de tu poder de ataque cada segundo (No se acumula)",
    -- addon:data.affix_text.every_third_revenge_turns_nearby_non_bos:text
    ["Every third Revenge turns nearby non-boss enemies to stone for 2 sec. When the stone breaks it shatters for @value@150%@value@ @range@[30%-150%]@range@ of your Attack Power to enemies around it (Does not stack)"] = "Cada tercera Revancha convierte en piedra durante 2 s a los enemigos cercanos que no sean jefes. Cuando la piedra se rompe, estalla con daño equivalente al @value@150%@value@ @range@[30%-150%]@range@ de tu poder de ataque a los enemigos de alrededor (No se acumula)",
    -- addon:callboard.every_contract_is_done_for:text
    ["Every {catName} contract is done for now.\nCome back after the reset."] = "Todos los contratos de {catName} están terminados por ahora.\nVuelve tras el reinicio.",
    -- addon:prestige.everything_else_is_untouched_your:text
    ["Everything else is untouched. Your level and your current run, your Echoes, permanent or not, your saved builds, your gear, your talents and professions, your Tomes, and every milestone reward you have earned."] = "Todo lo demás queda intacto. Tu nivel y tu expedición actual, tus Ecos, permanentes o no, tus builds guardadas, tu equipo, tus talentos y profesiones, tus Tomos y todas las recompensas de hito que hayas ganado.",
    -- addon:data.affix_text.eviscerate_leaves_a_shadowflame_cut_the:text
    ["Eviscerate leaves a Shadowflame cut: the target burns for @value@40%@value@ @range@[15%-40%]@range@ of the Eviscerate damage over 6 sec. If it dies while burning, the cut jumps to the nearest enemy and all your combo points are refunded (Does not stack)"] = "Eviscerar deja un corte de Llama de las Sombras: el objetivo arde y recibe un @value@40%@value@ @range@[15%-40%]@range@ del daño de Eviscerar durante 6 s. Si muere mientras arde, el corte salta al enemigo más cercano y recuperas todos tus puntos de combo (No se acumula)",
    -- addon:data.boss.exarch_maladaar:text
    ["Exarch Maladaar"] = "Exarca Maladaar",
    -- addon:data.affix_text.execute_also_slashes_every_enemy_in_a_co:text
    ["Execute also slashes every enemy in a cone in front of you for @value@200%@value@ @range@[40%-200%]@range@ of your Attack Power, split between them (Does not stack)"] = "Ejecutar también alcanza a todos los enemigos en un cono delante de ti con daño equivalente al @value@200%@value@ @range@[40%-200%]@range@ de tu poder de ataque, repartido entre ellos (No se acumula)",
