    -- addon:data.affix_family.explosive_barrage:text
    ["Explosive Barrage"] = "Tromba explosiva",
    -- addon:data.affix_text.explosive_shot_sets_the_target_ablaze_va:text
    ["Explosive Shot sets the target ablaze: @value@100%@value@ @range@[20%-100%]@range@ of your Attack Power as Fire damage every 2 sec for 10 sec, and every 2 sec the Burn spreads to a nearby enemy that is not burning (Does not stack)"] = "Disparo explosivo prende fuego al objetivo: daño de Fuego equivalente al @value@100%@value@ @range@[20%-100%]@range@ de tu poder de ataque cada 2 s durante 10 s, y cada 2 s la Quemadura se propaga a un enemigo cercano que no esté ardiendo (No se acumula)",
    -- addon:data.affix_text.explosive_trap_scatters_3_volatile_oozes:text
    ["Explosive Trap scatters 3 volatile oozes around it. Each explodes after 2 sec for @value@150%@value@ @range@[30%-150%]@range@ of your Attack Power and knocks back non-boss enemies (Does not stack)"] = "Trampa explosiva esparce 3 cienos volátiles a su alrededor. Cada uno explota tras 2 s con daño equivalente al @value@150%@value@ @range@[30%-150%]@range@ de tu poder de ataque, y los enemigos que no son jefes salen despedidos hacia atrás (No se acumula)",
