    ["Ice Tomb"] = "Tumba de hielo",
    -- addon:data.affix_text.icebound_fortitude_also_surrounds_you_wi:text
    ["Icebound Fortitude also surrounds you with a frost aura: enemies within 8 yd are slowed by 30 % and take @value@150%@value@ @range@[30%-150%]@range@ of your Attack Power as Frost damage every second (Does not stack)"] = "Entereza ligada al hielo también te rodea con un aura de escarcha: los enemigos en un radio de 8 m se ralentizan un 30 % y reciben daño de Escarcha equivalente al @value@150%@value@ @range@[30%-150%]@range@ de tu poder de ataque cada segundo (No se acumula)",
