    ["You are not in a guild."] = "No perteneces a ninguna hermandad.",
    -- addon:core.you_are_now_spectating:text
    ["You are now spectating."] = "Ahora estás en modo espectador.",
    -- addon:contracts.you_are_past_its_level:text
    ["You are past its level: nothing counts any more"] = "Has superado su nivel: ya nada cuenta",
    -- addon:worldChannel.you_can_always_join_later:text
    ["You can always join later with /join <channel> (e.g. /join world)"] = "Siempre puedes unirte más tarde con /join <canal> (p. ej. /join world)",
    -- addon:collections.gs_transmog_specs_button_tutorial:text
    ["You can apply this look to all your specializations, or just your current one."] = "Puedes aplicar este aspecto a todas tus especializaciones o solo a la actual.",
    -- addon:playerRun.you_can_come_back_by:text
    ["You can come back by paying part of your run: the first resurrection costs |cffffd70025%|r of its Soul Ashes and Shards, |cffff4040each next one 25% more|r. Another player can also resurrect you, once per run. The number is how many you paid this run. |cffff4040Accepting death|r ends the run."] = "Puedes volver pagando parte de tu expedición: la primera resurrección cuesta el |cffffd70025%|r de sus Cenizas de alma y Fragmentos, |cffff4040cada una de las siguientes un 25% más|r. Otro jugador también puede resucitarte, una vez por expedición. El número indica cuántas has pagado en esta expedición. |cffff4040Aceptar la muerte|r pone fin a la expedición.",
    -- addon:callboard.you_can_hold_up_to_5_of_each:text
    ["You can hold up to 5 of each."] = "Puedes tener hasta 5 de cada uno.",
    -- addon:collections.gs_err_no_riding_skill:text
