    -- addon:perks.orb_err_only_have:text
    ["You only have {count} Orb(s) of Lost Memories."] = "Solo tienes {count} Orbe(s) de los recuerdos perdidos.",
    -- addon:trials.you_play_a:text
    ["You play a {myClass}"] = "Juegas como {myClass}",
    -- addon:data.mountdesc.64659:text
    ["You raised this thing from a scaly pup - Mor'vek would be so proud. But he'd still make you clean up the mess it made in the corner."] = "Criaste a esta cosa desde que era un cachorro escamoso; Mor'vek estaría muy orgulloso. Pero aun así te haría limpiar el desastre que dejó en el rincón.",
    -- addon:affixToast.you_receive:text
    ["You receive"] = "Recibes",
    -- addon:data.mountdesc.59570:text
    ["You should never listen to minstrels' fancies. A dragon would never hurt a soul, unless they tried to hurt him first."] = "Nunca deberías hacer caso de las fantasías de los juglares. Un dragón jamás haría daño a nadie, a menos que intentaran hacérselo a él primero.",
    -- addon:skillTree.you_tried_to_import_a:text
    ["You tried to import a build without enough Soul Ashes (Required: {totalPointsRequired}, Available: {TALENTPOINTSTOTAL})"] = "Has intentado importar una configuración sin suficientes Cenizas de alma (necesarias: {totalPointsRequired}, disponibles: {TALENTPOINTSTOTAL})",
    -- addon:journal.you_unlocked_a_new_tome:text
    ["You unlocked a new Tome Echo! Open your Echo Journal to see it."] = "¡Has desbloqueado un nuevo Eco de tomo! Abre tu Diario de Ecos para verlo.",
    -- addon:journal.alert_tome_named:text
    ["You unlocked a new Tome Echo: |cffffd700{name}|r! Open your Echo Journal to see it."] = "¡Has desbloqueado un nuevo Eco de tomo: |cffffd700{name}|r! Abre tu Diario de Ecos para verlo.",
    -- addon:data.mountdesc.35028:text
    ["You watch what happens when their master is attacked and you will see those birds in a whole new light. - Raider Bork"] = "Fíjate en lo que pasa cuando atacan a su amo y verás a esos pájaros con otros ojos. - Asaltante Bork",
    -- addon:death.accept_confirm
    ["You will gain {gains} that you can spend in the Skill Tree.\n\nYour equipped gear will be sent to your inventory, and you will be reset to level 1 and teleported to your starting zone.\n\nAre you sure?"] = "Ganarás {gains} que podrás gastar en el Árbol de Cenizas.\n\nTu equipo se enviará a tu inventario, volverás al nivel 1 y se te teletransportará a tu zona de inicio.\n\n¿Seguro que quieres continuar?",
    -- addon:core.you_will_gain_soul_ashes:text
    ["You will gain {soulPointsGain} Soul Ashes and {soulShardsGain} Soul Shards."] = "Ganarás {soulPointsGain} Cenizas de alma y {soulShardsGain} Fragmentos de alma.",
    -- addon:core.you_will_gain_soul_ashes_2:text
    ["You will gain {soulPointsGain} Soul Ashes."] = "Ganarás {soulPointsGain} Cenizas de alma.",
    -- addon:callboard.you_will_start_in_cffffd100_zone_r_sub_y:text
    ["You will start in |cffffd100{zone}|r, {sub}. Your hearthstone will be bound there."] = "Empezarás en |cffffd100{zone}|r, {sub}. Tu piedra de hogar quedará vinculada allí.",
    -- addon:data.petdesc.59250:text
    ["You wouldn't want to meet this rat in a dark alley. Or anywhere else, for that matter."] = "No querrías encontrarte con esta rata en un callejón oscuro. Ni en ningún otro sitio, ya puestos.",
    -- addon:trials.you_top:text
    ["You |cffffffff#{myRank}|r/{total} · top |cffffffff{total2}%|r"] = "Tú |cffffffff#{myRank}|r/{total} · el |cffffffff{total2}%|r mejor",
    -- addon:collections.gs_transmogrify_tooltip_appearance_known:text
    ["You've collected this appearance"] = "Has conseguido esta apariencia",
    -- addon:collections.gs_transmogrify_tooltip_item_unknown_appearance_known:text
    ["You've collected this appearance, but not from this item"] = "Has conseguido esta apariencia, pero no con este objeto",
    -- addon:collections.gs_err_completed_transmog_set_s:text
    ["You've completed the set %s."] = "Has completado el conjunto %s.",
    -- addon:data.affix_text.your_beacon_of_light_target_takes_value:text
    ["Your Beacon of Light target takes @value@15%@value@ @range@[3%-15%]@range@ less damage, and Beacon of Light cleanses one harmful magic effect from it every 10 sec (Does not stack)"] = "El objetivo de tu Señal de la Luz recibe un @value@15%@value@ @range@[3%-15%]@range@ menos de daño, y Señal de la Luz le disipa un efecto mágico perjudicial cada 10 s (No se acumula)",
    -- addon:data.affix_text.your_death_and_decay_becomes_felmyst_s_d:text
    ["Your Death and Decay becomes Felmyst's demonic vapor: it deals @value@50%@value@ @range@[10%-50%]@range@ more damage, and enemies that die in it rise as ghouls that fight for you for 10 sec (Does not stack)"] = "Tu Muerte y descomposición se convierte en el vapor demoníaco de Brumavil: inflige un @value@50%@value@ @range@[10%-50%]@range@ más de daño, y los enemigos que mueren en él se alzan como necrófagos que luchan por ti durante 10 s (No se acumula)",
    -- addon:data.affix_text.your_earth_shield_target_also_takes_valu:text
    ["Your Earth Shield target also takes @value@15%@value@ @range@[3%-15%]@range@ less magic damage (Does not stack)"] = "El objetivo de tu Escudo de tierra también recibe un @value@15%@value@ @range@[3%-15%]@range@ menos de daño mágico (No se acumula)",
    -- addon:data.affix_text.your_earthbind_totem_roots_the_first_ene:text
    ["Your Earthbind Totem roots the first enemies it slows for 2 sec, up to @value@6@value@ @range@[2-6]@range@ enemies, once every 15 sec (Does not stack)"] = "Tu Tótem Nexo Terrestre inmoviliza durante 2 s a los primeros enemigos que ralentiza, hasta @value@6@value@ @range@[2-6]@range@ enemigos, una vez cada 15 s (No se acumula)",
    -- addon:journal.your_echoes:text
    ["Your Echoes"] = "Tus Ecos",
    -- addon:data.affix_text.your_fire_damage_may_hurl_a_fiery_ball_d:text
    ["Your Fire damage may hurl a fiery ball dealing @value@100%@value@ @range@[20%-100%]@range@ of your Spell Power or Attack Power as Fire damage, plus the same amount over 8 sec (Does not stack)"] = "Tu daño de Fuego puede lanzar una bola ígnea que inflige daño de Fuego equivalente al @value@100%@value@ @range@[20%-100%]@range@ de tu poder con hechizos o tu poder de ataque, más la misma cantidad durante 8 s (No se acumula)",
    -- addon:data.affix_text.your_frost_damage_may_launch_a_bolt_of_f:text
    ["Your Frost damage may launch a bolt of frost dealing @value@100%@value@ @range@[20%-100%]@range@ of your Spell Power or Attack Power as Frost damage and slowing the target by 30% for 5 sec, increased by 20% per slowing effect on the target (Does not stack)"] = "Tu daño de Escarcha puede lanzar una descarga de escarcha que inflige daño de Escarcha equivalente al @value@100%@value@ @range@[20%-100%]@range@ de tu poder con hechizos o tu poder de ataque y ralentiza al objetivo un 30% durante 5 s, un 20% más por cada efecto de ralentización que tenga el objetivo (No se acumula)",
    -- addon:data.affix_text.your_immolate_leaves_a_trail_of_doomfire:text
    ["Your Immolate leaves a trail of Doomfire behind the target as it moves: enemies in it burn for @value@50%@value@ @range@[10%-50%]@range@ of your Spell Power every second (Does not stack)"] = "Tu Inmolar deja un rastro de Fuego apocalíptico tras el objetivo cuando se mueve: los enemigos que están en él arden y sufren daño equivalente al @value@50%@value@ @range@[10%-50%]@range@ de tu poder con hechizos cada segundo (No se acumula)",
    -- addon:data.affix_text.your_nature_damage_may_coat_the_target_i:text
    ["Your Nature damage may coat the target in Corrosive Acid dealing @value@67%@value@ @range@[13%-67%]@range@ of your Spell Power or Attack Power as Nature damage every 3 sec for 15 sec and reducing its armor by 10% per periodic effect you have on it (up to 30%) (Does not stack)"] = "Tu daño de Naturaleza puede cubrir al objetivo de Ácido corrosivo, que inflige daño de Naturaleza equivalente al @value@67%@value@ @range@[13%-67%]@range@ de tu poder con hechizos o tu poder de ataque cada 3 s durante 15 s y reduce su armadura un 10% por cada efecto periódico tuyo que tenga (hasta un 30%) (No se acumula)",
    -- addon:raidFinder.your_raid_finder_raid_n_total_players:text
    ["Your Raid Finder raid: {n} / {total} players."] = "Tu banda del Buscador de bandas: {n} / {total} jugadores.",
    -- addon:raidFinder.your_raid_is_ready:text
    ["Your Raid Is Ready"] = "Tu banda está lista",
    -- addon:data.affix_text.your_shadow_damage_may_send_a_shadowy_bo:text
    ["Your Shadow damage may send a shadowy bolt dealing @value@100%@value@ @range@[20%-100%]@range@ of your Spell Power or Attack Power as Shadow damage, increased by 20% per Shadow periodic effect you have on the target (Does not stack)"] = "Tu daño de Sombras puede enviar una descarga sombría que inflige daño de Sombras equivalente al @value@100%@value@ @range@[20%-100%]@range@ de tu poder con hechizos o tu poder de ataque, un 20% más por cada efecto periódico de Sombras tuyo que tenga el objetivo (No se acumula)",
    -- addon:skillTree.your_skill_tree:text
    ["Your Skill Tree"] = "Tu Árbol de Cenizas",
    -- addon:prestige.your_skill_tree_is_reset:text
    ["Your Skill Tree is reset, and every Soul Ash on the account is destroyed: the ones you banked and the ones already spent, on every character. The Ashes buy nothing back. Only |cff00FF00Carry over Prestige|r nodes survive the reset, and they become free for good. Every |cff00FF00Endless|r node is one of them: all its ranks stay."] = "Tu Árbol de Cenizas se reinicia y se destruyen todas las Cenizas de alma de la cuenta: las que depositaste y las ya gastadas, en todos los personajes. Las Cenizas no te devuelven nada. Solo sobreviven al reinicio los nodos de |cff00FF00Prestigio transferible|r, y pasan a ser gratuitos para siempre. Todo nodo |cff00FF00Sin fin|r es uno de ellos: se conservan todos sus rangos.",
    -- addon:data.affix_text.your_spirit_wolves_heal_you_for_value_20:text
    ["Your Spirit Wolves heal you for @value@20%@value@ @range@[20%-60%]@range@ of the damage they deal (Does not stack)"] = "Tus lobos espirituales te sanan un @value@20%@value@ @range@[20%-60%]@range@ del daño que infligen (no se acumula)",
    -- addon:data.affix_text.your_spirit_wolves_heal_you_for_value_30:text
    ["Your Spirit Wolves heal you for @value@30%@value@ @range@[20%-60%]@range@ of the damage they deal (Does not stack)"] = "Tus lobos espirituales te sanan un @value@30%@value@ @range@[20%-60%]@range@ del daño que infligen (no se acumula)",
    -- addon:data.affix_text.your_spirit_wolves_heal_you_for_value_40:text
    ["Your Spirit Wolves heal you for @value@40%@value@ @range@[20%-60%]@range@ of the damage they deal (Does not stack)"] = "Tus lobos espirituales te sanan un @value@40%@value@ @range@[20%-60%]@range@ del daño que infligen (no se acumula)",
    -- addon:data.affix_text.your_spirit_wolves_heal_you_for_value_50:text
    ["Your Spirit Wolves heal you for @value@50%@value@ @range@[20%-60%]@range@ of the damage they deal (Does not stack)"] = "Tus lobos espirituales te sanan un @value@50%@value@ @range@[20%-60%]@range@ del daño que infligen (no se acumula)",
    -- addon:data.affix_text.your_spirit_wolves_heal_you_for_value_60:text
    ["Your Spirit Wolves heal you for @value@60%@value@ @range@[20%-60%]@range@ of the damage they deal (Does not stack)"] = "Tus lobos espirituales te sanan un @value@60%@value@ @range@[20%-60%]@range@ del daño que infligen (no se acumula)",
    -- addon:playerRun.your_torment:text
    ["Your Torment: {tier}"] = "Tu Tormento: {tier}",
    -- addon:toolbelt.chat_not_discovered:text
    ["Your account has not discovered that waystone."] = "Tu cuenta no ha descubierto esa piedra de paso.",
    -- addon:itemPurchase.your_attacks_have_a_chance:text
    ["Your attacks have a chance to infect the target, dealing Shadow damage every 3 sec for 15 sec. If the target dies before the effect expires, the infection spreads to a nearby enemy, retaining its remaining duration."] = "Tus ataques tienen una probabilidad de infectar al objetivo e infligirle daño de Sombras cada 3 s durante 15 s. Si el objetivo muere antes de que termine el efecto, la infección se propaga a un enemigo cercano y conserva la duración restante.",
    -- addon:prestige.your_banked_soul_shards_are:text
    ["Your banked Soul Shards are consumed with the Ashes and come back as |cffFFCC00Soul Essence|r, one for every 750 Shards. This card shows the exchange you would make right now.\n\nSoul Essence buys the Prestige branch of the Skill Tree, and it is the only currency a prestige never takes back: it only ever grows."] = "Tus Fragmentos de alma depositados se consumen con las Cenizas y vuelven como |cffFFCC00Esencia de alma|r, una por cada 750 Fragmentos. Esta tarjeta muestra el intercambio que harías ahora mismo.\n\nLa Esencia de alma compra la rama de Prestigio del Árbol de Cenizas, y es la única moneda que un prestigio nunca se lleva: solo puede crecer.",
    -- addon:prestige.your_banked_soul_shards_are_consumed_wit:text
    ["Your banked Soul Shards are consumed with the Ashes and come back as |cffFFCC00Soul Essence|r: one for every 50 Shards on your first Prestige, 50 Shards more each time, up to 750. Your first Prestige mints at most 50 Soul Essence, the next 100, up to 750 on the 15th, then there is no limit. Shards above the limit stay banked. This card shows the exchange you would make right now.\n\nSoul Essence buys the Prestige branch of the Skill Tree, and it is the only currency a prestige never takes back: it only ever grows."] = "Tus Fragmentos de alma depositados se consumen con las Cenizas y vuelven como |cffFFCC00Esencia de alma|r: una por cada 50 Fragmentos en tu primer Prestigio, 50 Fragmentos más cada vez, hasta 750. Tu primer Prestigio genera como máximo 50 Esencias de alma, el siguiente 100, hasta 750 en el decimoquinto; después no hay límite. Los Fragmentos por encima del límite siguen depositados. Esta tarjeta muestra el intercambio que harías ahora mismo.\n\nLa Esencia de alma compra la rama de Prestigio del Árbol de Cenizas, y es la única moneda que un prestigio nunca se lleva: solo puede crecer.",
    -- addon:trials.your_best:text
    ["Your best: |cffffffff{myBest}|r"] = "Tu mejor marca: |cffffffff{myBest}|r",
    -- addon:perks.tip_refused:text
    ["Your build refuses this echo"] = "Tu build rechaza este eco",
    -- addon:skillTree.your_changes_were_not_applied:text
    ["Your changes were not applied."] = "No se han aplicado tus cambios.",
    -- addon:raidFinder.your_class_cannot_take_this_role:text
    ["Your class cannot take this role."] = "Tu clase no puede asumir este rol.",
    -- addon:skillTree.your_class_level_does_not:text
    ["Your class level does not allow another node yet."] = "Tu nivel de clase aún no permite otro nodo.",
    -- addon:skillTree.your_class_progress_is_not:text
    ["Your class progress is not loaded yet, try again."] = "El progreso de tu clase aún no se ha cargado, inténtalo de nuevo.",
    -- addon:playerRun.your_contracts:text
    ["Your contracts"] = "Tus contratos",
    -- addon:data.mountdesc.60116:text
    ["Your cries of \"For the Horde!\" will be much more menacing from atop a heavily armored bear that's barreling down on Alliance at top speed."] = "Tus gritos de \"¡Por la Horda!\" sonarán mucho más amenazadores desde lo alto de un oso fuertemente acorazado que se abalanza a toda velocidad sobre la Alianza.",
    -- addon:data.affix_text.your_critical_heals_heal_for_an_addition:text
    ["Your critical heals heal for an additional @value@50%@value@ @range@[10%-50%]@range@ (Does not stack)"] = "Tus sanaciones críticas sanan un @value@50%@value@ @range@[10%-50%]@range@ adicional (No se acumula)",
    -- addon:data.affix_text.your_critical_strikes_corrupt_the_target:text
    ["Your critical strikes corrupt the target for @value@67%@value@ @range@[13%-67%]@range@ of your Spell Power or Attack Power as Shadow damage every 3 sec for 15 sec; your critical strikes make an existing Corruption flare for the same amount (once every 6 sec) (Does not stack)"] = "Tus golpes críticos corrompen al objetivo y le infligen daño de Sombras equivalente al @value@67%@value@ @range@[13%-67%]@range@ de tu poder con hechizos o tu poder de ataque cada 3 s durante 15 s; tus golpes críticos hacen que una Corrupción ya activa estalle e inflija esa misma cantidad de daño (una vez cada 6 s) (No se acumula)",
    -- addon:data.affix_text.your_critical_strikes_may_send_a_shockwa:text
    ["Your critical strikes may send a shockwave dealing @value@135%@value@ @range@[27%-135%]@range@ of your Attack Power or Spell Power as Physical damage to all enemies within 8 yards of the target (Does not stack)"] = "Tus golpes críticos pueden enviar una onda de choque que inflige daño Físico equivalente al @value@135%@value@ @range@[27%-135%]@range@ de tu poder de ataque o tu poder con hechizos a todos los enemigos en un radio de 8 m del objetivo (No se acumula)",
    -- addon:torment.your_current_difficulty:text
    ["Your current difficulty"] = "Tu dificultad actual",
    -- addon:data.affix_text.your_damaging_spells_and_abilities_may_f:text
    ["Your damaging spells and abilities may fire an Infinite Star dealing Arcane damage equal to @value@x1,7@value@ @range@[x0,3-x1,7]@range@ your highest stat (Does not stack)"] = "Tus hechizos y habilidades de daño pueden disparar una Estrella infinita que inflige daño de Arcano igual a @value@x1,7@value@ @range@[x0,3-x1,7]@range@ tu característica más alta (No se acumula)",
    -- addon:data.affix_text.your_damaging_spells_and_abilities_may_r:text
    ["Your damaging spells and abilities may release a Frozen Pulse dealing Shadow damage equal to @value@67%@value@ @range@[13%-67%]@range@ of your Attack Power or Spell Power every second for 6 sec (Does not stack)"] = "Tus hechizos y habilidades de daño pueden liberar un Pulso congelado que inflige daño de Sombras equivalente al @value@67%@value@ @range@[13%-67%]@range@ de tu poder de ataque o tu poder con hechizos cada segundo durante 6 s (No se acumula)",
    -- addon:perks.your_echo_is_here_click_this_button_to_o:text
    ["Your echo is here! Click this button to open |cffffd700Character Progression|r, your echoes are in the |cffffd700Echoes|r tab."] = "¡Aquí está tu eco! Haz clic en este botón para abrir |cffffd700Progresión del personaje|r; tus ecos están en la pestaña |cffffd700Ecos|r.",
    -- addon:perks.your_echo_is_in_cffffd700character_progr:text
    ["Your echo is in |cffffd700Character Progression|r, |cffffd700Echoes|r tab. Type |cffffd700/collections|r to open it."] = "Tu eco está en |cffffd700Progresión del personaje|r, pestaña |cffffd700Ecos|r. Escribe |cffffd700/collections|r para abrirla.",
    -- addon:perks.your_echoes_are_not_loaded_yet_try_again:text
    ["Your echoes are not loaded yet. Try again in a moment."] = "Tus ecos aún no se han cargado. Inténtalo de nuevo en un momento.",
    -- addon:journal.your_echoes_skill_tree_transmogrify:text
    ["Your echoes, skill tree, transmogrify, mounts and companions."] = "Tus ecos, Árbol de Cenizas, transfiguración, monturas y mascotas.",
    -- addon:callboard.your_first_contract_claimed_today_gives:text
    ["Your first contract claimed today gives you one Elixir of Ashes and one Elixir of Shards."] = "Tu primer contrato reclamado hoy te da un Elixir de cenizas y un Elixir de fragmentos.",
    -- addon:data.affix_text.your_heals_may_grant_you_sanctified_ward:text
    ["Your heals may grant you Sanctified Ward for 15 sec, during which your heals also shield the target for @value@25%@value@ @range@[5%-25%]@range@ of the amount healed (Does not stack)"] = "Tus sanaciones pueden otorgarte Resguardo santificado durante 15 s. Mientras dura, tus sanaciones también protegen al objetivo con un escudo equivalente al @value@25%@value@ @range@[5%-25%]@range@ de la cantidad sanada (No se acumula)",
    -- addon:extraction.your_item:text
    ["Your item"] = "Tu objeto",
    -- addon:shop.toast_delivered:text
    ["Your item has been delivered."] = "Se ha entregado tu objeto.",
    -- addon:toolbelt.chat_macro_full:text
    ["Your macro list is full. Delete a macro to place this waystone on an action bar."] = "Tu lista de macros está llena. Borra una macro para colocar esta piedra de paso en una barra de acción.",
    -- addon:prestige.your_next_milestone_reward_is:text
    ["Your next milestone reward is previewed here. Hover any milestone to preview its mount or transmog set."] = "Aquí se muestra una vista previa de la recompensa de tu próximo hito. Pasa el ratón sobre cualquier hito para ver su montura o conjunto de transfiguración.",
    -- addon:dungeonFinder.your_next_run_is_at:text
    ["Your next run is at this difficulty"] = "Tu próxima expedición será con esta dificultad",
    -- addon:dungeonFinder.your_party:text
    ["Your party"] = "Tu grupo",
    -- addon:dungeonFinder.your_party_only:text
    ["Your party only"] = "Solo tu grupo",
    -- addon:data.affix_text.your_periodic_heals_heal_for_an_addition:text
    ["Your periodic heals heal for an additional @value@25%@value@ @range@[5%-25%]@range@ (Does not stack)"] = "Tus sanaciones periódicas sanan un @value@25%@value@ @range@[5%-25%]@range@ adicional (No se acumula)",
    -- addon:data.affix_text.your_pets_deal_value_10_value_range_10_5:text
    ["Your pets deal @value@10%@value@ @range@[10%-50%]@range@ more damage and attack @value@5%@value@ @range@[5%-25%]@range@ faster (Does not stack)"] = "Tus mascotas infligen un @value@10%@value@ @range@[10%-50%]@range@ más de daño y atacan un @value@5%@value@ @range@[5%-25%]@range@ más rápido (No se acumula)",
    -- addon:data.affix_text.your_pets_deal_value_16_value_range_10_5:text
    ["Your pets deal @value@16%@value@ @range@[10%-50%]@range@ more damage and attack @value@8%@value@ @range@[5%-25%]@range@ faster (Does not stack)"] = "Tus mascotas infligen un @value@16%@value@ @range@[10%-50%]@range@ más de daño y atacan un @value@8%@value@ @range@[5%-25%]@range@ más rápido (No se acumula)",
    -- addon:data.affix_text.your_pets_deal_value_24_value_range_10_5:text
    ["Your pets deal @value@24%@value@ @range@[10%-50%]@range@ more damage and attack @value@12%@value@ @range@[5%-25%]@range@ faster (Does not stack)"] = "Tus mascotas infligen un @value@24%@value@ @range@[10%-50%]@range@ más de daño y atacan un @value@12%@value@ @range@[5%-25%]@range@ más rápido (No se acumula)",
    -- addon:data.affix_text.your_pets_deal_value_34_value_range_10_5:text
    ["Your pets deal @value@34%@value@ @range@[10%-50%]@range@ more damage and attack @value@17%@value@ @range@[5%-25%]@range@ faster (Does not stack)"] = "Tus mascotas infligen un @value@34%@value@ @range@[10%-50%]@range@ más de daño y atacan un @value@17%@value@ @range@[5%-25%]@range@ más rápido (No se acumula)",
    -- addon:data.affix_text.your_pets_deal_value_50_value_range_10_5:text
    ["Your pets deal @value@50%@value@ @range@[10%-50%]@range@ more damage and attack @value@25%@value@ @range@[5%-25%]@range@ faster (Does not stack)"] = "Tus mascotas infligen un @value@50%@value@ @range@[10%-50%]@range@ más de daño y atacan un @value@25%@value@ @range@[5%-25%]@range@ más rápido (No se acumula)",
    -- addon:contracts.your_progress_is_lost:text
    ["Your progress ({progress} / {required}) is lost. "] = "Tu progreso ({progress} / {required}) se perderá. ",
    -- addon:callboard.your_quest_log_is_full:text
    ["Your quest log is full."] = "Tu registro de misiones está lleno.",
    -- addon:raidFinder.your_raid_is_ready_2:text
    ["Your raid is ready!"] = "¡Tu banda está lista!",
    -- addon:playerRun.your_run:text
    ["Your run"] = "Tu expedición",
    -- addon:core.your_run_does_not_hold:text
    ["Your run does not hold enough Soul Ashes."] = "Tu expedición no tiene suficientes Cenizas de alma.",
    -- addon:playerRun.your_run_your_collection_and:text
    ["Your run, your collection and all existing echoes"] = "Tu expedición, tu colección y todos los ecos existentes",
    -- addon:raidFinder.your_seat_role:text
    ["Your seat: {role}"] = "Tu plaza: {role}",
    -- addon:contracts.your_soul_is_anchored_to:text
    ["Your soul is anchored to this spirit. Releasing it is free."] = "Tu alma está anclada a este espíritu. Liberarla es gratis.",
    -- addon:contracts.your_soul_is_anchored_to_2:text
    ["Your soul is anchored to {anchorPlace}. Move it here for the run's Soul Ashes."] = "Tu alma está anclada a {anchorPlace}. Muévela aquí por las Cenizas de alma de la expedición.",
    -- addon:data.affix_text.your_spells_and_abilities_have_a_chance:text
    ["Your spells and abilities have a chance to make your next spell or ability cost nothing, about @value@10@value@ @range@[4-10]@range@ times per minute (Does not stack)"] = "Tus hechizos y habilidades tienen una probabilidad de hacer que tu siguiente hechizo o habilidad no cueste nada, unas @value@10@value@ @range@[4-10]@range@ veces por minuto (No se acumula)",
    -- addon:data.affix_text.your_spells_and_abilities_may_wound_the:text
    ["Your spells and abilities may Wound the target for @value@135%@value@ @range@[27%-135%]@range@ of your Attack Power or Spell Power; twice as likely from behind (Does not stack)"] = "Tus hechizos y habilidades pueden causar Herida al objetivo e infligirle un daño equivalente al @value@135%@value@ @range@[27%-135%]@range@ de tu poder de ataque o poder con hechizos, con el doble de probabilidad por la espalda (no se acumula)",
    -- addon:data.affix_text.your_spells_and_abilities_may_blast_the:text
    ["Your spells and abilities may blast the target with lightning dealing @value@67%@value@ @range@[13%-67%]@range@ of your Spell Power or Attack Power as Nature damage, jumping to 4 more enemies and making each victim take 25% more Nature damage from you for 12 sec; the primary target is caught in a cyclone slowing its attacks by 20% for 12 sec (Does not stack)"] = "Tus hechizos y habilidades pueden fulminar al objetivo con un relámpago que inflige daño de Naturaleza equivalente al @value@67%@value@ @range@[13%-67%]@range@ de tu poder con hechizos o tu poder de ataque, salta a 4 enemigos más y hace que cada víctima reciba un 25% más de daño de Naturaleza tuyo durante 12 s; el objetivo principal queda atrapado en un ciclón que ralentiza sus ataques un 20% durante 12 s (No se acumula)",
    -- addon:data.affix_text.your_spells_and_abilities_may_call_forth:text
    ["Your spells and abilities may call forth an Ember Guardian for 15 sec, dealing @value@135%@value@ @range@[27%-135%]@range@ of its normal damage (once every 30 sec) (Does not stack)"] = "Tus hechizos y habilidades pueden invocar a un Guardián de ascuas durante 15 s, que inflige un @value@135%@value@ @range@[27%-135%]@range@ de su daño normal (una vez cada 30 s) (No se acumula)",
    -- addon:data.affix_text.your_spells_and_abilities_may_disarm_the:text
    ["Your spells and abilities may disarm the target for @value@3 sec@value@ @range@[1 sec-3 sec]@range@ (once every 15 sec) (Does not stack)"] = "Tus hechizos y habilidades pueden desarmar al objetivo durante @value@3 s@value@ @range@[1 s-3 s]@range@ (una vez cada 15 s) (No se acumula)",
    -- addon:data.affix_text.your_spells_and_abilities_may_hurl_a_fie:text
    ["Your spells and abilities may hurl a fiery ball dealing @value@100%@value@ @range@[20%-100%]@range@ of your Spell Power or Attack Power as Fire damage plus the same amount over 10 sec, increased by 10% per Fire periodic effect you have on the target (Does not stack)"] = "Tus hechizos y habilidades pueden lanzar una bola ígnea que inflige daño de Fuego equivalente al @value@100%@value@ @range@[20%-100%]@range@ de tu poder con hechizos o tu poder de ataque, más la misma cantidad durante 10 s, un 10% más por cada efecto periódico de Fuego tuyo que tenga el objetivo (No se acumula)",
    -- addon:data.affix_text.your_spells_and_abilities_may_increase_t:text
    ["Your spells and abilities may increase the target's spell damage taken by @value@5%@value@ @range@[1%-5%]@range@ for 5 sec (Does not stack)"] = "Tus hechizos y habilidades pueden aumentar el daño de hechizos que recibe el objetivo un @value@5%@value@ @range@[1%-5%]@range@ durante 5 s (No se acumula)",
    -- addon:data.affix_text.your_spells_and_abilities_may_increase_y:text
    ["Your spells and abilities may increase your critical strike damage by @value@50%@value@ @range@[10%-50%]@range@ for 10 sec (Does not stack)"] = "Tus hechizos y habilidades pueden aumentar tu daño de golpe crítico un @value@50%@value@ @range@[10%-50%]@range@ durante 10 s (No se acumula)",
    -- addon:data.affix_text.your_spells_and_abilities_may_inflict_a:text
    ["Your spells and abilities may inflict a Fatal Wound dealing Physical damage equal to @value@135%@value@ @range@[27%-135%]@range@ of your Attack Power or Spell Power (Does not stack)"] = "Tus hechizos y habilidades pueden infligir una Herida fatal que causa daño Físico equivalente al @value@135%@value@ @range@[27%-135%]@range@ de tu poder de ataque o tu poder con hechizos (No se acumula)",
    -- addon:data.affix_text.your_spells_and_abilities_may_poison_the:text
    ["Your spells and abilities may poison the target for @value@135%@value@ @range@[27%-135%]@range@ of your Attack Power or Spell Power over 8 sec; poisoned targets take 5% more damage from your periodic effects (Does not stack)"] = "Tus hechizos y habilidades pueden envenenar al objetivo con un @value@135%@value@ @range@[27%-135%]@range@ de tu poder de ataque o tu poder con hechizos durante 8 s; los objetivos envenenados reciben un 5% más de daño de tus efectos periódicos (No se acumula)",
    -- addon:data.affix_text.your_spells_and_abilities_may_restore_va:text
    ["Your spells and abilities may restore @value@10%@value@ @range@[2%-10%]@range@ of your maximum resource (once every 6 sec) (Does not stack)"] = "Tus hechizos y habilidades pueden restaurar un @value@10%@value@ @range@[2%-10%]@range@ de tu recurso máximo (una vez cada 6 s) (No se acumula)",
    -- addon:data.affix_text.your_spells_and_abilities_may_smite_the:text
    ["Your spells and abilities may smite the target for @value@100%@value@ @range@[20%-100%]@range@ of your Spell Power or Attack Power as Holy damage (Does not stack)"] = "Tus hechizos y habilidades pueden castigar al objetivo con daño de Sagrado equivalente al @value@100%@value@ @range@[20%-100%]@range@ de tu poder con hechizos o tu poder de ataque (No se acumula)",
    -- addon:data.affix_text.your_spells_and_abilities_may_strike_the:text
